/**
 * Service Worker Registration
 * Registers the PWA service worker generated by vite-plugin-pwa (production
 * builds only), which caches the app shell so Salin opens without a network.
 * Shows a toast when offline use is ready and when an update is waiting.
 */

import { registerSW } from "virtual:pwa-register";

import { toast } from "@/stores/toast-store";

export function registerServiceWorker() {
  if (!("serviceWorker" in navigator)) return;
  const updateServiceWorker = registerSW({
    immediate: true,
    onNeedRefresh() {
      toast("A new version of e-Vet is ready.", { label: "Reload", onClick: () => void updateServiceWorker(true) }, { duration: null });
    },
    onOfflineReady() {
      toast("e-Vet is ready to work offline.");
    },
    onRegisterError(error: unknown) {
      console.error("Service worker registration failed", error);
    },
  });
}
